sys_script_include.script:
var serviceDependencyKPI = Class.create();
serviceDependencyKPI.prototype = {
    initialize: function() {
        // Use a default weight for each dependency record since no additional relationship fields exist.
        this.defaultWeight = 1;
    },
    calculate: function() {
        var serviceGr = new GlideRecord('cmdb_ci_service');
        serviceGr.addQuery('operational_status', 1);
        serviceGr.query();
        var analysis = [];
        while (serviceGr.next()) {
            analysis.push(this._analyzeDependencies(serviceGr));
        }
        return {
            dependency_analysis: analysis,
            summary: this._generateSummary(analysis)
        };
    },
    _analyzeDependencies: function(service) {
        // Query the association table using the "service_id" field.
        var assocGr = new GlideRecord('svc_ci_assoc');
        assocGr.addQuery('service_id', service.getUniqueValue());
        assocGr.query();
        var dependencies = {
            service_name: service.getValue('name'),
            total_components: 0,
            dependency_chains: [],
            risk_score: 0
        };
        while (assocGr.next()) {
            dependencies.total_components++;
            this._processDependencyChain(assocGr, dependencies);
        }
        dependencies.risk_score = this._calculateRiskScore(dependencies);
        return dependencies;
    },
    _processDependencyChain: function(assoc, dependencies) {
        // Retrieve the dependent component's name using the "ci_item_id" field.
        var componentName = assoc.getUniqueValue();
        // Build a simple dependency chain description.
        var chain = "Depends on " + componentName;
        dependencies.dependency_chains.push(chain);
        // Accumulate risk using the default weight.
        dependencies.risk_score += this.defaultWeight;
    },
    _calculateRiskScore: function(dependencies) {
        // Calculate an average risk score per dependency if any exist.
        if (dependencies.total_components > 0) {
            return dependencies.risk_score / dependencies.total_components;
        }
        return 0;
    },
    _generateSummary: function(analysis) {
        var summary = {
            total_services: analysis.length,
            total_components: 0,
            average_risk_score: 0
        };
        var totalRisk = 0;
        for (var i = 0; i < analysis.length; i++) {
            summary.total_components += analysis[i].total_components;
            totalRisk += analysis[i].risk_score;
        }
        summary.average_risk_score = (analysis.length > 0) ? totalRisk / analysis.length : 0;
        return summary;
    }
};
